import sqlite3, os, binascii
for p in ['/app/main.db','/app/main.db-wal']:
    with open(p,'rb') as f:
        d=f.read(256)
    print('\n==',p,os.path.getsize(p),'==')
    for i in range(0,len(d),16):
        print(f'{i:04x}:',binascii.hexlify(d[i:i+16]).decode(), ''.join(chr(c) if 32<=c<127 else '.' for c in d[i:i+16]))
try:
    con=sqlite3.connect('file:/app/main.db?mode=ro',uri=True)
    print('\n=== DB ===')
    print('journal_mode',con.execute('pragma journal_mode').fetchall())
    print('integrity',con.execute('pragma integrity_check').fetchall())
    print('schema',con.execute("select type,name,tbl_name,sql from sqlite_master").fetchall())
    for (name,) in con.execute("select name from sqlite_master where type='table'"):
        print(name, con.execute(f'select * from "{name}"').fetchall())
except Exception as e: print('DB ERROR',type(e).__name__,e)
